/**
 * IV therapy & treatments (§7) — the module where a software bug becomes a
 * regulated-medicine problem, so the safety rules are structural rather than
 * copy. Three of them shape everything below.
 *
 * 1. **The catalogue is code, not data.** `TREATMENT_PROTOCOLS` is defined here
 *    and reviewed in pull requests. It is deliberately NOT a database table an
 *    admin screen can edit, and deliberately NOT generated by the model: in the
 *    UK a prescription-only medicine may not be advertised to the public
 *    (Human Medicines Regulations 2012, reg. 279), and the fastest way to break
 *    that is to let an LLM invent a protocol name. Nothing here names a
 *    substance, a dose, or a route of administration.
 *
 * 2. **The "why" restates the user's own data and claims nothing.** Same rule
 *    as `nutritionRead`: the reason is computed from readings the user logged,
 *    so it can only ever tell them what they already recorded. A trigger says
 *    "you logged low energy on 3 of the last 7 days" — never that a protocol
 *    would raise it. That sentence is a health claim and we do not make one.
 *
 * 3. **Approval is an act, never a default.** There is no path from REQUESTED
 *    to APPROVED except a practitioner deciding. Silence does not approve, time
 *    does not approve, and an approval expires rather than standing forever.
 *    `canProceedToBooking` is the only function permitted to say a booking may
 *    go ahead, and every caller must route through it.
 *
 * A personal trainer can never review one of these — see `canReview`.
 */
import { z } from "zod";

/**
 * The sentence that must appear wherever a suggestion is shown. Exported as a
 * constant so it cannot drift between surfaces, and so a test can assert it is
 * present rather than trusting a screen to carry it.
 */
export const TREATMENT_DISCLAIMER =
  "Wellness suggestion only. A practitioner will review your booking.";

/** Shown once a request exists, replacing the suggestion-time disclaimer. */
export const TREATMENT_PENDING_NOTE =
  "Nothing is booked. A practitioner reviews every request before anything goes ahead.";

/**
 * The footer on every card in the practitioner's approvals queue (design 5B).
 *
 * Two sentences doing two jobs: the first is the ASA/CAP-facing statement of
 * what this service is, the second tells the practitioner their decision is
 * recorded against their name — which is true (`recordAuditTx`) and is the
 * reason the decision feels like one.
 */
export const TREATMENT_QUEUE_DISCLAIMER =
  "General wellness service — not medical treatment, diagnosis or advice. Your decision is logged.";

/** The lead paragraph under the queue header. */
export const TREATMENT_QUEUE_LEAD =
  "Bookings stay on hold until you decide. Declining requires a reason, which is shared with the client.";

/**
 * Minimum characters in a decline reason, mirroring `treatmentDecisionInput`.
 *
 * Exported so the client can gate its own button on the same number rather than
 * discovering the rule by being rejected. The design enables Confirm on any
 * non-empty text; we hold the stricter server rule and say so in the hint,
 * because "Confirm" that fails is worse than "Confirm" that waits.
 */
export const MIN_DECLINE_REASON = 10;

/** How long a practitioner's approval stays good for. */
export const APPROVAL_TTL_DAYS = 30;

/** Lookback window for every trigger below, in days. */
export const SIGNAL_WINDOW_DAYS = 7;

/* ------------------------------------------------------------------ */
/* The catalogue                                                       */
/* ------------------------------------------------------------------ */

/** Which logged signal a protocol is surfaced from. One trigger per protocol. */
export const treatmentTrigger = z.enum([
  "LOW_ENERGY",
  "LOW_HYDRATION",
  "LOW_SLEEP",
  "LOW_READINESS",
]);
export type TreatmentTrigger = z.infer<typeof treatmentTrigger>;

export type TreatmentProtocol = {
  /** Stable identifier stored on the request. Never renumber or reuse one. */
  slug: string;
  /** A category of consultation, not a formulation. */
  name: string;
  /** What the appointment IS — no outcome, no benefit, no claim. */
  summary: string;
  trigger: TreatmentTrigger;
  /** Days within the window that must show the signal before we surface it. */
  threshold: number;
};

/**
 * The complete catalogue.
 *
 * Every `name` is a *consultation category*, never a product: "Hydration
 * review", not a named infusion. Every `summary` describes what happens at the
 * appointment — an assessment — and none of them says the appointment will make
 * anyone feel better, because we do not know that and are not permitted to say
 * it. Adding an entry here is a regulatory change, not a content change: it
 * needs the same review as a schema migration.
 */
export const TREATMENT_PROTOCOLS: readonly TreatmentProtocol[] = [
  {
    slug: "energy-review",
    name: "Energy review",
    summary:
      "A practitioner reviews your recent energy readings and discusses whether any treatment is appropriate.",
    trigger: "LOW_ENERGY",
    threshold: 3,
  },
  {
    slug: "hydration-review",
    name: "Hydration review",
    summary:
      "A practitioner reviews your hydration log and discusses whether any treatment is appropriate.",
    trigger: "LOW_HYDRATION",
    threshold: 3,
  },
  {
    slug: "sleep-review",
    name: "Sleep review",
    summary:
      "A practitioner reviews your recent sleep readings and discusses whether any treatment is appropriate.",
    trigger: "LOW_SLEEP",
    threshold: 3,
  },
  {
    slug: "recovery-review",
    name: "Recovery review",
    summary:
      "A practitioner reviews your readiness trend and discusses whether any treatment is appropriate.",
    trigger: "LOW_READINESS",
    threshold: 4,
  },
] as const;

/** Look up a protocol by the slug stored on a request. */
export function protocolBySlug(slug: string): TreatmentProtocol | null {
  return TREATMENT_PROTOCOLS.find((p) => p.slug === slug) ?? null;
}

/**
 * The name to show for a slug that is no longer in the catalogue.
 *
 * A retired protocol must not make an existing request unrenderable — the user
 * asked for something and is owed a record of it, so old rows degrade to a
 * neutral label rather than disappearing from their history.
 */
export function protocolName(slug: string): string {
  return protocolBySlug(slug)?.name ?? "Treatment review";
}

/* ------------------------------------------------------------------ */
/* Suggestion — deterministic, from the user's own readings            */
/* ------------------------------------------------------------------ */

/**
 * Counts of days in the window that showed each signal. Assembled by the API
 * from the user's OWN rows; nothing here reaches outside their record.
 */
export type TreatmentSignals = {
  lowEnergyDays: number;
  lowHydrationDays: number;
  lowSleepDays: number;
  lowReadinessDays: number;
};

export type TreatmentSuggestion = {
  slug: string;
  name: string;
  summary: string;
  /** The user's own count, restated. Never a claim about what would help. */
  reason: string;
  /** Days observed, so the client can render the count without parsing prose. */
  observedDays: number;
  threshold: number;
};

function daysFor(trigger: TreatmentTrigger, s: TreatmentSignals): number {
  switch (trigger) {
    case "LOW_ENERGY":
      return s.lowEnergyDays;
    case "LOW_HYDRATION":
      return s.lowHydrationDays;
    case "LOW_SLEEP":
      return s.lowSleepDays;
    case "LOW_READINESS":
      return s.lowReadinessDays;
  }
}

/** The noun phrase a reason sentence is built around. */
const SIGNAL_NOUN: Record<TreatmentTrigger, string> = {
  LOW_ENERGY: "low energy",
  LOW_HYDRATION: "low hydration",
  LOW_SLEEP: "short sleep",
  LOW_READINESS: "low readiness",
};

/**
 * Which protocols this user's own readings surface, strongest signal first.
 *
 * Pure and total: the same signals always produce the same suggestions, which
 * is what makes this reviewable. There is no model anywhere in this path — see
 * the header. A suggestion is an invitation to ask a practitioner, and the
 * reason string restates the user's log, phrased so it cannot be read as a
 * promise about what a treatment would do.
 */
export function suggestTreatments(signals: TreatmentSignals): TreatmentSuggestion[] {
  return TREATMENT_PROTOCOLS.map((p) => ({ p, days: daysFor(p.trigger, signals) }))
    .filter(({ p, days }) => days >= p.threshold)
    .sort((a, b) => b.days - a.days || a.p.slug.localeCompare(b.p.slug))
    .map(({ p, days }) => ({
      slug: p.slug,
      name: p.name,
      summary: p.summary,
      reason: `You logged ${SIGNAL_NOUN[p.trigger]} on ${days} of the last ${SIGNAL_WINDOW_DAYS} days.`,
      observedDays: days,
      threshold: p.threshold,
    }));
}

/**
 * What counts as "low" for each signal.
 *
 * Deliberately here rather than in the API resolver: these numbers decide when
 * someone is invited to ask about a treatment, which makes them the closest
 * thing in this codebase to clinical judgement. They belong in reviewed, tested,
 * pure code where a change to one is visible in a diff — not buried in a query.
 *
 * All four are intentionally conservative. A threshold that is too eager turns
 * the feature into an upsell that follows people around after one bad night,
 * which is exactly the failure mode the ASA's rules on health claims exist to
 * prevent.
 */
export const SIGNAL_THRESHOLDS = {
  /** `DailyLog.energy` is 1–5; 2 or below is the bottom two rungs the user picked. */
  energyAtOrBelow: 2,
  /** `DailyLog.sleepHours`. Below 6 is the widely-cited short-sleep mark. */
  sleepHoursBelow: 6,
  /** `Metric` HYDRATION, millilitres logged for that day. */
  hydrationMlBelow: 1500,
  /** `ReadinessSnapshot.score`, 0–100. */
  readinessBelow: 50,
} as const;

/**
 * One day of the user's own readings. Every field is nullable because a missing
 * reading is not a low reading — a day the user didn't log must never count
 * towards a suggestion, or the app would surface treatments at people for not
 * opening it.
 */
export type SignalDay = {
  energy: number | null;
  sleepHours: number | null;
  hydrationMl: number | null;
  readiness: number | null;
};

/** Count how many days in the window showed each signal. Pure; null never counts. */
export function countSignals(days: readonly SignalDay[]): TreatmentSignals {
  const below = (v: number | null, limit: number): boolean => v !== null && v < limit;
  const atOrBelow = (v: number | null, limit: number): boolean => v !== null && v <= limit;
  return {
    lowEnergyDays: days.filter((d) => atOrBelow(d.energy, SIGNAL_THRESHOLDS.energyAtOrBelow)).length,
    lowHydrationDays: days.filter((d) => below(d.hydrationMl, SIGNAL_THRESHOLDS.hydrationMlBelow)).length,
    lowSleepDays: days.filter((d) => below(d.sleepHours, SIGNAL_THRESHOLDS.sleepHoursBelow)).length,
    lowReadinessDays: days.filter((d) => below(d.readiness, SIGNAL_THRESHOLDS.readinessBelow)).length,
  };
}

/* ------------------------------------------------------------------ */
/* The request lifecycle                                               */
/* ------------------------------------------------------------------ */

export const treatmentStatus = z.enum([
  "REQUESTED",
  "APPROVED",
  "DECLINED",
  "WITHDRAWN",
  "EXPIRED",
]);
export type TreatmentStatus = z.infer<typeof treatmentStatus>;

/** Statuses from which nothing further can happen. */
export const TERMINAL_STATUSES: readonly TreatmentStatus[] = [
  "DECLINED",
  "WITHDRAWN",
  "EXPIRED",
] as const;

export function isTerminal(status: TreatmentStatus): boolean {
  return TERMINAL_STATUSES.includes(status);
}

/**
 * A request still occupying the queue — i.e. one the client cannot duplicate.
 *
 * APPROVED counts: an approved-but-unbooked request is live, and stacking a
 * second one behind it would put two authorisations for the same protocol in
 * play at once.
 */
export function isOpen(status: TreatmentStatus): boolean {
  return status === "REQUESTED" || status === "APPROVED";
}

/** Who is attempting a transition. */
export type TreatmentActor = "CLIENT" | "PRACTITIONER" | "SYSTEM";

/**
 * The complete transition table. Anything not listed here is refused.
 *
 * Written as data rather than as branches so the whole lifecycle can be read at
 * once and asserted exhaustively in a test. Note what is absent and must stay
 * absent: nothing reaches APPROVED except a PRACTITIONER acting, and SYSTEM can
 * only ever expire an approval that already exists — it can never create one.
 */
const TRANSITIONS: ReadonlyArray<{
  from: TreatmentStatus;
  to: TreatmentStatus;
  actor: TreatmentActor;
}> = [
  { from: "REQUESTED", to: "APPROVED", actor: "PRACTITIONER" },
  { from: "REQUESTED", to: "DECLINED", actor: "PRACTITIONER" },
  { from: "REQUESTED", to: "WITHDRAWN", actor: "CLIENT" },
  // A client may still back out after approval — an approval is permission,
  // not an obligation.
  { from: "APPROVED", to: "WITHDRAWN", actor: "CLIENT" },
  { from: "APPROVED", to: "EXPIRED", actor: "SYSTEM" },
];

export function canTransition(
  from: TreatmentStatus,
  to: TreatmentStatus,
  actor: TreatmentActor,
): boolean {
  return TRANSITIONS.some((t) => t.from === from && t.to === to && t.actor === actor);
}

/**
 * Whether a staff capability may review treatment requests.
 *
 * PT is refused, and this is the most important line in the file: a personal
 * trainer is not a clinician, and no amount of consent from the client can make
 * them one. Unlike every other staff surface in this codebase, this one is NOT
 * consent-widenable — the ceiling is the capability itself, and the client is
 * not offered a control that would lower it.
 */
export function canReview(kind: "PT" | "PRACTITIONER"): boolean {
  return kind === "PRACTITIONER";
}

/** When an approval granted at `approvedAt` stops being valid. */
export function approvalExpiresAt(approvedAt: Date): Date {
  return new Date(approvedAt.getTime() + APPROVAL_TTL_DAYS * 24 * 60 * 60 * 1000);
}

/**
 * The ONLY function permitted to say a booking may proceed.
 *
 * Everything about §7 funnels through this one predicate so there is exactly
 * one place to audit. It is deliberately strict about its inputs: a missing
 * `approvedAt` on an APPROVED row is treated as not-approved rather than as
 * "approved at an unknown time", because an unreadable authorisation is not an
 * authorisation.
 */
export function canProceedToBooking(
  req: { status: TreatmentStatus; approvedAt: Date | null },
  now: Date = new Date(),
): boolean {
  if (req.status !== "APPROVED") return false;
  if (req.approvedAt === null) return false;
  return approvalExpiresAt(req.approvedAt).getTime() > now.getTime();
}

/**
 * The status to SHOW, given the time — as opposed to the status stored.
 *
 * The `status` column records what a person decided; expiry is a property of
 * the clock, not a decision. Deriving it here means an approval reads as lapsed
 * the instant it lapses, with no background job to fall behind, and means a
 * query never has to write. The stored APPROVED row stays intact as the record
 * that a practitioner did approve, on that date.
 */
export function effectiveStatus(
  req: { status: TreatmentStatus; approvedAt: Date | null },
  now: Date = new Date(),
): TreatmentStatus {
  if (req.status === "APPROVED" && !canProceedToBooking(req, now)) return "EXPIRED";
  return req.status;
}

/** Whole days until an approval lapses; 0 once it has. */
export function daysUntilExpiry(approvedAt: Date, now: Date = new Date()): number {
  const ms = approvalExpiresAt(approvedAt).getTime() - now.getTime();
  return ms <= 0 ? 0 : Math.ceil(ms / (24 * 60 * 60 * 1000));
}

/* ------------------------------------------------------------------ */
/* Inputs                                                              */
/* ------------------------------------------------------------------ */

/** Requesting a review. The slug must be one we actually publish. */
export const treatmentRequestInput = z.object({
  slug: z.string().refine((s) => protocolBySlug(s) !== null, {
    message: "Unknown treatment protocol",
  }),
  /** Optional note from the client to the reviewing practitioner. */
  note: z.string().trim().max(500).optional(),
});
export type TreatmentRequestInput = z.infer<typeof treatmentRequestInput>;

export const treatmentIdInput = z.object({ id: z.string().uuid() });
export type TreatmentIdInput = z.infer<typeof treatmentIdInput>;

/**
 * A decision. A decline REQUIRES a reason — a bare refusal tells the client
 * nothing and leaves them no route forward, and the §9 brief specifies
 * "approve/decline + reason". An approval takes an optional note.
 */
export const treatmentDecisionInput = z.discriminatedUnion("decision", [
  z.object({
    id: z.string().uuid(),
    decision: z.literal("APPROVE"),
    note: z.string().trim().max(500).optional(),
  }),
  z.object({
    id: z.string().uuid(),
    decision: z.literal("DECLINE"),
    reason: z.string().trim().min(MIN_DECLINE_REASON).max(500),
  }),
]);
export type TreatmentDecisionInput = z.infer<typeof treatmentDecisionInput>;
